import sys

def min_string(s):
    balance = [0]
    for c in s:
        balance.append(balance[-1] + ('0' == c))
    min_str = []
    i = 0
    while balance and balance[-1] % 2 == 0:
        balance.pop()
        min_str.append(s[i])
        i += 1
    for c in reversed(s):
