def swap(i, j, S):
    S = list(S)
    S[i], S[j] = S[j], S[i]
    return ''.join(S)

def get_lexicographically_smallest_string(N, S):
    for i in range(1, N-1):
        if ord(S[i]) - ord(S[i-1]) > ord(S[i+1]) - ord(S[i]):
            S = swap(i, i+1, S)
    return ''.join(S)

T = int(input())
for _ in range(T):
    N = int(input())
    S = input()
