from collections import deque

def find_shortest_path(n, m, corridors):
    # Add a virtual cave and starting position
    initial_adjacency = {1: []}
    for i in range(1, n):
        initial_adjacency[i] = [1]

    # Add actual data
    for u, v in corridors:
        initial_adjacency[u].append(v)
        initial_adjacency[v].append(u)

    # Depth-first search to build the shortest path
    def dfs(start, end, visited):
        queue = deque([(start, [start])])
        while queue:
            node, path = queue.popleft()
            for neighbor in initial_adjacency[node]:
                if neighbor not in visited and neighbor != end:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
                elif neighbor == end:
                    return path + [neighbor]

    path = dfs(1, n, set())
    if path:
        return len(path) - 1, path[1:]
    else:
        return -1

# Example usage
