        return 'YES', []

    # Build a graph of clauses that reference each variable
    ref_graph = defaultdict(int)
    for cl in clauses:
        for lit in cl:
            ref_graph[lit] += 1

    graph = {k: [] for k in range(m)}
    for lit, cnt in ref_graph.items():
        graph[lit].append(cnt)
        graph[lit * 2].append(cnt)

    # Check if the graph can be modified to have a cycle
    visited = set()
    def dfs(k):
        if k in visited:
            return False
        visited.add(k)
        queue = [k]
        while queue:
            cur = queue.pop()
            if cur in graph:
                for cnt in graph[cur]:
                    if cnt - 1 in graph and dfs(cnt - 1):
                        return True
                    if cnt + 1 in graph and dfs(cnt + 1):
