from collections import deque, defaultdict
import heapq
from heapq import heappush, heappop
class UnionFind:
    def __init__(self, size):
        self.parent = [i for i in range(size)]

    def find(self, x):
        if self.parent[x] != x:
            return self.find(self.parent[x])
        return x

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_y] = root_x

class VerticalOrderTreeWalk:
    def __init__(self):
        self.ans = 0
        self.N = 0
        self.Q = 0
        self.arr = []
        self.verts = defaultdict(list)
        self.ans_set = defaultdict(list)
        self.edges = defaultdict(list)

    def input(self, rows):
        for i in range(self.N - 1):
            v = int(rows[i])
            self.verts[v].extend([i + 1, i + 2])
        for i in range(self.N):
            self.verts[i + 1].append(i + 1)

    def find_and_merge(self, x, y, price):
        x_root = self.find(x)
        y_root = self.find(y)
        self.ans = min(self.ans, price)

        if x_root != y_root:
            self.ans_set[max(x_root, y_root)].append((price, x, y))

    def dfs_non_self(self, level, node):
        self.ans += (-self.arr[node])
        self.ans_set[level].append((-self.arr[node], node))
        for to_node in self.verts[node]:
            if to_node != self.verts[node][0] and to_node != self.verts[node][-1]:
                self.dfs_non_self(level + 1, to_node)

    def dfs_to_price(self, level, node, price, level_price, prev_level):
        if level_price > self.N:
            level_price = self.N
        for to_node in self.verts[node]:
            if to_node != self.verts[node][0] and to_node != self.verts[node][-1]:
                self.dfs_to_price(level + 1, to_node, min(price + self.arr[node], self.arr[prev_level] + level_price), level_price + self.arr[node], level_price)

    def dfs(self, node, priority, prev_level):
        self.dfs_to_price(1, node, priority, priority, prev_level)
        self.dfs_non_self(1, node)
        self.ans += priority

    def solve(self, n, MIN, MAX, queries):
        self.ans = ~MAX
        for i in range(n):
            self.verts[i + 1].sort()
            heappush(self.edges[i + 1], (-self.arr[i + 1], i + 1))
        union_find = UnionFind(n)
        for query in queries:
            SNODE, DNODE, W = query
            self.arr = []
            INVALID = (0 << 1) - 1
            for j in range(SNODE, SNODE + 1):
                self.arr.append(-(self.arr[union_find.find(j)]))
                union_find.union(union_find.find(j), union_find.find(DNODE))
                SNODE = DNODE
            for j in range(DNODE, DNODE + 1):
                self.arr.append(-(self.arr[union_find.find(j)]))
                union_find.union(union_find.find(j), union_find.find(SNODE))
                DNODE = SNODE
            self.arr = reversed(self.arr)
            total = INVALID
            for i in range(INVALID, len(self.arr)):
                total = min(total, (-self.arr[i]) + (self.arr[union_find.find(DNODE)] + (-self.arr[i])) + (-self.arr[union_find.find(SNODE)]))
                union_find.union(union_find.find(SNODE), union_find.find(DNODE))
            self.arr = []
            for j in range(MIN, MAX + 1):
                valid = True
                for snode in range(SNODE, DNODE):
