def lex_smallest_rotatable_string(s):
    lst = []
    for i, c in enumerate(s):
        nxt_lst = []
        if i > 0 and s[i] != s[i-1]:
            nxt_lst.append((s[i-1], i-1))
        if i > 0 and i < len(s) - 1 and s[i] != s[i+1]:
            nxt_lst.append((s[i+1], i+1))
        lst.append((c, i, nxt_lst))
    lst.sort(key=lambda x: (x[1], -ord(x[0])))

    queue = [(-len(s)-1, -ord(s[-1]))]
    seen = [False] * (len(s) + 1)
    seen[-1] = True
    for x, order in lst:
        seen[order] = True
        for c, next_order in nxt_lst:
            if not seen[next_order]:
                if c < queue[0][-1]:
                    seen[next_order] = True
                    heappush(queue, (ord(c), -next_order))
                elif c == queue[0][-1] and order < queue[0][1]:
                    seen[next_order] = True
                    heappush(queue, (ord(c), -next_order))
        if queue[0][-1] < -ord(x):
            heappop(queue)
            seen[order] = True
            heappush(queue, (ord(x), -order))

    return ''.join(chr(-q[1]) for q in queue)

