def find_shortest_subsequence(nums, d):
    prefix_sum = [0] * len(nums)
    prefix_sum[0] = nums[0]
    for i in range(1, len(nums)):
        prefix_sum[i] = prefix_sum[i-1] + nums[i]

    start, end, min_length = 0, 0, float('inf')
    for i in range(len(nums)):
        while start <= i and (i - start + 1) * (prefix_sum[i] - prefix_sum[start-1]) < 2 * d:
            min_length = min(min_length, i - start + 1)
            if i < len(nums) - 1:
                end += 1
            else:
                break
        start += 1

    if min_length == float('inf'):
        return -1
    else:
        return min_length

