from collections import deque

def reverse_crux(s, index1, index2):
    return s[:index1+1] + s[index2+1:index1:-1] + s[index2+1:index1][::-1] + s[index2+1:]

def smallest_lexicographical(s):
    queue = deque([s])
    visited = set()

    while queue:
        current = queue.popleft()
        if current in visited:
            continue
        visited.add(current)
        for i in range(len(current) - 1):
            if current[i] == current[i+1]:
                if reverse_crux(current, i, i+1) not in visited:
                    queue.append(reverse_crux(current, i, i+1))
        if current[-1] == "a":
            if current[:-1] not in visited:
                queue.append(deque([current[:-1]]))
            if current[:-1] == deque([current[-1]]):
                break

    return tuple(sorted(queue, key = ''.join))

