import sys

def least_frequent_bit(x):
    return bin(x).count('1')

def max_gcd(a, b):
    return a if a == 0 else max_gcd(b, a % b)

def solve(N, M, K):
    if N == 2:
        return [1, 1]

    bits_count = 0
    for i in range(32):
        counter = 0
        shifted = i
        while shifted <= N:
            counter += (shifted % 2) * (1 << i)
            shifted *= 2
            if shifted == N + 1:
                bits_count += 1
    if bits_count > max_gcd(M, K):
        return -1

    bits_needed = min(32 - bits_count, M)
    bit_prefix_sum = [0] * 32

    for i in range(32):
        if least_frequent_bit(i) > max_gcd(M, K):
            continue
        bit_prefix_sum[i] = (1 << (31 - i - 1)) & 31
        counter = 0
        for j in range(K):
            if (1 << j) & i:
                counter = counter + bit_prefix_sum[i - counter - 1]
        if counter == M:
            break

    prefix_sum = [0] * (N + 1)
    values = [0] * M

    for i in range(K):
        prefix_sum[i + 1] = prefix_sum[i] + bit_prefix_sum[values[i]]

    j = M - 1
    while 31 in bit_prefix_sum:
        if j - 1 >= 0:
            prefix_sum[j - 1] = prefix_sum[j] - (1 << bits_needed - 1)
        prefix_sum[j] = prefix_sum[j] + min(256 - bits_needed, (1 << bits_needed) - 1)
        values[j] = (1 << (31 - (most_frequent_bit(prefix_sum[j]) >> bits_needed)))
        j -= 1
    values.reverse()
    for i in range(1, N + 1):
        values[i] = (i - prefix_sum[i]) >> (bits_needed - 1)

    return values

