import math

def find_schedule(n, C):
    if n <= 4:
        for d in range(4, 8):
            if math.comb(C, d) == n:
                return d, d+1
    else:
        # Precompute factorials and inverse factorials to avoid overflow
        fac = [0] * (n + 1)
        inv_fac = [0] * (n + 1)
        fac[0] = 1
        for i in range(1, n + 1):
            fac[i] = fac[i - 1] * i
        inv_fac[n] = modular_inverse(fac[n], 998244353)
        for i in range(n - 1, 0, -1):
            inv_fac[i] = inv_fac[i + 1] * (i + 1)

        for main_index in range(5, n + 1):
            objective = [math.comb(C, i) for i in range(n - main_index + 1)]
            for sub_index in range(n - main_index + 1):
                a = objective[sub_index] - objective[n - sub_index * main_index - 1] + 1
                if math.comb(C, a) == main_index:
                    return main_index, sub_index * main_index
                elif math.comb(C, a) == main_index - 1:
                    return main_index - 1, sub_index * main_index

def modular_inverse(a, m):
    """Computes the modular inverse of a under modulo m using Fermat's little theorem."""
    return pow(a, m - 2, m)

