from collections import defaultdict, deque

def dijkstra(graph, start, num_nodes):
    distances = {node: float('inf') for node in range(num_nodes)}
    distances[start] = 0
    visited = [False] * num_nodes
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = priority_queue.pop(0)

        if visited[current_node]:
            continue

        visited[current_node] = True

        for neighbor, weight in graph[current_node].items():
            distance = distances[current_node] + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                priority_queue.append((distance, neighbor))

    return distances

def find_min_path(graph, num_nodes):
    if all(distance not in {0, num_nodes-1} for distance in graph.values()):
        return -1

    distances = dijkstra(graph, 0, num_nodes)

    min_distance = float('inf')
    start_node = None
    end_node = None

    for node, distance in distances.items():
        if distance == distances[num_nodes-1] and distance != 0:
            start_node = node
            end_node = num_nodes-1
            break

    if start_node is None:
        return -1

    queue = deque([(start_node, [start_node])])
    visited = [False] * num_nodes

    while queue:
        current_node, path = queue.popleft()

        if current_node == end_node:
            return len(path)

        for neighbor, _ in graph[current_node].items():
            if neighbor not in path and visited[neighbor] == False:
                visited[neighbor] = True
                queue.append((neighbor, path + [neighbor]))

    return -1

