from collections import defaultdict

def find_minimum_time(n, m, passages):
    # Create a graph with time intervals for each passage
    graph = defaultdict(list)
    for a, b, l, r in passages:
        graph[a].append((b, l, r))
        graph[b].append((a, l, r))

    # Sort the graph entries by time per side
    for start, directions in graph.items():
        for end, l, r in sorted(directions):
            if r <= l:
                return -1  # Impossible to get from A to B in our time window

    minimum_time = float('inf')

    # Min/Max queries over ends using binary search
    def get_minimum_time(start):
        l, r = 0, min_time
        while l < r:
            mid = l + (r - l) // 2
            if graph[start]:
                for end, l, r in sorted(graph[start]):
                    if mid >= r:
                        break
                    minimum_time = min(minimum_time, mid - l)
            else:
                break
            if mid >= r:
                break
            r = mid

        return minimum_time + 1

    # Initialize minimum_time, max_time
    max_time = 0
    for _, directions in graph.items():
        for end, l, r in sorted(directions):
            max_time = max(max_time, r)
            if end == n:
                minimum_time = min(minimum_time, l-1)

    # Find ceil and floor time of start point
    lower_bound = int(min(max_time, (float('inf') - 1) // (n-1)))
    upper_bound = int(min_time)

    while lower_bound < upper_bound:
        mid = (lower_bound + upper_bound) // 2
        if get_minimum_time(mid) >= float('inf'):
            lower_bound = mid + 1
        else:
            upper_bound = mid

    return upper_bound - 1

