from typing import List

def flip_char(char: str) -> str:
    if char == '0':
        return '1'
    else:
        return '0'

def reverse_substring(s: str, start: int, end: int) -> str:
    return s[:start] + s[end:start:-1] + s[end+1:]
    
def solve(s: str) -> str:
    stack = []
    for i, c in enumerate(s):
        if len(stack) == 0:
            stack.append((i, c))
        else:
            if stack[-1][1] == c:
                stack.pop()
            else:
                stack.append((i, c))

    smallest_string = s
    for start, end in stack:
        new_string = s[start:end+1]
        flipped_string = flip_char(new_string)
        if flipped_string < smallest_string:
            smallest_string = flipped_string
        reversed_string = reverse_substring(s, start, end)
        if reversed_string < smallest_string:
            smallest_string = reversed_string

    return smallest_string

def main() -> None:
