from collections import deque

def transform_string(s):
    """Transform the string by flipping substrings containing equal number of 0's and 1's."""
    stack = deque()
    flips = 0
    result = ""

    for char in s:
        if char == '0':
            flips += 1
        else:
            flips -= 1

        if not stack or stack[0] != '1' or stack[1] != '0':
            stack.append('1')
            if flips % 2 == 0:
                stack.append('1')
            else:
                stack.append('0')
            flips = 0
        result += stack.popleft()

    if flips % 2 == 0:
        stack.append('1')
    else:
        stack.append('0')

    return ''.join(stack)

def smallest_possible_string(s):
    """Find the smallest possible string by applying the operation."""
    min_string = s
    for i in range(1, len(s) + 1):
        transformed = transform_string(s[:i])
        if transformed < min_string:
            min_string = transformed
    return min_string

