            if dp[i % 2][j] < total_energy:
                total_energy = dp[i % 2][j]

        # Handle the case where the frog ends up at any stone i
        dp[i % 2][i-1] = stones[i-2] if i-1 >= 0 else 0

    return min(total_energy, 0 if total_energy > 0 else 1)

