def flip_string(s):
    flip = []
    count = 0
    for char in s:
        if count == 0:
            flip.append('1' if char == '0' else '0')
            count += 1
        else:
            flip.append(char)
            count -= 1
    return ''.join(flip)

def reverse_string(s):
    return s[::-1]

def solve(s):
    result = ''
    index = 0
    while index < len(s):
        non_zero_end = index
        while non_zero_end + 1 < len(s) and s[non_zero_end + 1] == '1':
            non_zero_end += 1
        zero_start = index
        while zero_start > 0 and s[zero_start - 1] == '0':
            zero_start -= 1
        if non_zero_end - zero_start > 1:
            min_length = min(non_zero_end - zero_start, len(s) - non_zero_end - zero_start + 1)
            part = s[zero_start:non_zero_end + 1][:min_length]
            flipped = flip_string(part)
            reversed_part = reverse_string(flipped)
            result += flipped[:min_length] + reversed_part
            index = non_zero_end + 1
        else:
            result += s[index]
            index += 1
    return result

