def find_sequence(N, C):
    # Calculate the maximum possible sequence length
    max_possible = 1 + (C - 1)
    # Calculate the minimum possible sequence length
    min_possible = 2 * (C - 1)

    # Start with the minimum possible sequence length and incrementally check for longer sequences
    for i in range(2 * (C - 1) + 1, N + 1):
        bitmask = 0
        for j in range(1, i):
            if (j & (j >> 1)):
                bitmask = i
                break
        if bitmask < (C - 1):
            continue
        # Check if C - 1 values appear at least once in the sequence of length i
        seen = [0] * i
        for j in range(1, i):
            if (j & (j >> 1)):
                seen[j] += 1
                if seen[j] > 1:
                    break
        else:
            return sorted([i - 1, i])
    return [N, N]

