    graph = defaultdict(list)
    for u, v, y in edges:
        graph[u].append((v, y))
        graph[v].append((u, y))

    # Initialize the stack for level order traversal
    stack = [(0, -1, -1, float('inf'))]
    valid_sequences = []

    while stack:
        u, p, index, max_edge_value = stack.pop()

        if index == n-1:
            # Found a valid sequence
            if k == 0:
                return valid_sequences
            else:
                k -= 1
                # If we have k valid sequences left, we can discard the first one
                if k > 0:
                    continue
                else:
                    # Fetch the next valid sequence (lexicographically sorted)
                    index, max_edge_value = graph[u][0]
                    valid_sequences.append([v for i, (v, _), edge in enumerate(graph[u]) if i == index])
        else:
            for v, y in graph[u]:
                if v == p or y > max_edge_value:
                    continue
