def find_min_time(n, m, passages):
    graph = [[] for _ in range(n + 1)]
    for a, b, l, r in passages:
        graph[a].append((r - l, a, b))
        graph[b].append((r - l, a, b))

    def dijkstra(start, end, visited, dist, in_queue):
        if start == end:
            return dist[end]
        if start in visited:
            return float('inf')
        visited.add(start)
        dist[start] = 0
        pq = [(0, start)]
        in_queue.add((0, start))
        while pq:
            cost, node = heappop(pq)
            if not in_queue[node]:
                in_queue.remove((cost, node))
                for next_cost, next_node in graph[node]:
                    next_dist = dist[node] + next_cost
                    if next_dist < dist.get(next_node, float('inf')):
                        dist[next_node] = next_dist
                        heappush(pq, (next_dist, next_node))
        return float('inf')

