            cost, node = heappop(queue)
            if node == 1:
                prev[1] = visit_time
                break
            if node in visited:
                continue
            visited.add(node)
            visit_time = cost + max(node, 1)
            out_time = cost + (n - node)
            in_queue.add((out_time, node))

            for next_time in range(max(node + 1, (max(node, 1) + 10**9) // visit_time * visit_time),
                                  min(n + 1, (min(node, (n + 1) * (visit_time + 1)) // visit_time * visit_time) + 1)):
                next_node = next_time // visit_time
                for next_cost, next_node in graph[node]:
                    if dist[next_node] > cost + next_cost:
                        dist[next_node] = cost + next_cost
                        heappush(queue, (cost + next_cost, next_node))
            for next_time in range(out_time + 1, (out_time + 10**9) // visit_time * visit_time + 1):
                next_node = next_time // visit_time
                if dist[next_node] > cost:
                    dist[next_node] = cost
                    heappush(queue, (cost, next_node))

    dijkstra(1, n, set(), dist, set())
    return dist[n] if not visited[n] else -1

# Example usage
