def find_cards( oranges, apples ):
    # Base case: if there are no oranges and apples left, return "Impossible"
    if oranges == 0 and apples == 0:
        return "Impossible"

    # Define a recursive function to find the sequence of cards
    def find_sequence(card_count, oranges, apples):
        if card_count == 0:
            return (oranges, apples)

        if apples == 0:
            return (1, card_count + 1)

        if oranges <= apples:
            # Alice's move
            return (1, card_count + 1) + find_sequence(card_count - 1, oranges - 1, apples)
        else:
            # Bob's move
            current = find_sequence(card_count - apple_count + 1, oranges, apples - apple_count)
            return (
                (oranges - 1) // (card_count - apple_count),
                min(card_count - apple_count + 1, apples + 1),
                current[1], current[2] + 1
            )

    # Calculate the sequence of cards
    sequence = find_sequence(card_count=3, oranges=oranges, apples=apples)

    # Construct the answer as a compressed string
    answer = ""
    while sequence[0] > 0 or sequence[1] > 0:
        answer += str(sequence[0])
        sequence = tuple(sequence[1:])

    return answer

