import sys
from collections import defaultdict

def dijkstra(g, s):
    # Create adjacency list of graph g and initialize distances
    adj = defaultdict(list)
    dist = {}

    for u, v in g:
        adj[u].append(v)
        adj[v].append(u)

    # Queue, used to keep track of nodes to be accessed next
    queue = [(0, s)]
    dist[s] = 0

    while queue:
        d, u = queue.pop(0)

        # Check if a shorter path to u is available
        if u in dist and d > dist[u]: 
            continue

        for v in adj[u]:
            if v not in dist or dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                queue.append((dist[v], v))

    return dist

