from collections import defaultdict,deque

def findMinTime(n, m, passages):
    graph = defaultdict(list)
    for a, b, l, r in passages:
        graph[a-1].append((b-1, r-l))
        graph[b-1].append((a-1, r-l))

    min_time = [float('inf')] * n
    queue = deque()

    for i in range(n):
        if i == 0:
            min_time[i] = 0
            queue.append(i)
        else:
            queue.append(i)
            while queue:
                node = queue.popleft()
                for neighbor, duration in graph[node]:
                    if min_time[node] + duration < min_time[neighbor]:
                        min_time[neighbor] = min_time[node] + duration
                        queue.append(neighbor)
    for i in max(min_time):
        if i:
            return i

