from bisect import bisect_right

def find_shortest_subsequence(n, d):
    nums = []
    s = 0
    for x in nums:
        if x >= d:
            return 1
        s += x
        i = bisect_right(nums, d - s)
        if i < len(nums) and nums[i] > d - s:
            return i + 1

def solve(t):
    for _ in range(t):
        n, d = map(int, input().split())
        nums = list(map(int, input().split()))

        if any(x < d or x > 0 for x in nums):
            print(-1)
        else:
            shortest = n + 1
            for i in range(n + 1):
                max_sum = sum(nums[i:]) + sum(nums[:i])
                shortest = min(shortest, find_shortest_subsequence(-1, max_sum))

            print(shortest - 1)

